// Traductor de entrada para Sara.
//
// Nuestro aviso (evento message.inbound) llega con una forma distinta a la que Sara espera.
// Este nodo hace la traduccion UNA VEZ, en la puerta, en lugar de tocar 292 referencias.
//
// Entrada: el aviso de nuestra API.
// Salida:  los campos que Sara lee hoy, mas el aviso original intacto.

const entrada = $input.first().json;
const aviso = entrada.body ?? entrada;

const conversacion = aviso.conversation ?? {};
const mensaje = aviso.message ?? {};

const nombre = String(conversacion.contactName ?? '').trim();
const plataforma = String(conversacion.platform ?? '').toLowerCase();

// Sara lee el texto en la raiz ('body'), y nuestro aviso lo manda anidado.
const texto = String(mensaje.body ?? '');

// subscriber_id es el identificador interno de ManyChat y NO existe en nuestro lado.
// Se rellena con el identificador de la conversacion para que los flujos que solo lo usan
// como clave sigan funcionando. La marca 'identidad_manychat' avisa de que no es el original:
// cada vez que un flujo llame a ManyChat con el, esa llamada debe sustituirse por nuestra API.
const conversationId = String(aviso.conversationId ?? '');

return [{
  json: {
    // --- Campos que Sara espera ---
    body: texto,
    subscriber_id: conversationId,
    conversation_id: conversationId,
    conversationId: conversationId,
    first_name: nombre.split(' ')[0] ?? '',
    last_name: nombre.split(' ').slice(1).join(' '),
    canal_origen: plataforma,
    // Vacio a proposito: es una URL de ManyChat y no la tenemos. Los flujos comprueban si
    // viene o no, asi que el vacio es la respuesta honesta.
    live_chat_url: '',

    // --- Nuestros datos, para que los flujos nuevos los usen ---
    weplash_conversation_id: conversationId,
    weplash_tenant_id: String(aviso.tenantId ?? ''),
    weplash_message_id: String(aviso.messageId ?? ''),
    weplash_contact_name: nombre,
    weplash_contact_username: String(conversacion.contactUsername ?? ''),
    weplash_channel: plataforma,
    weplash_channel_name: String(conversacion.channelName ?? ''),
    weplash_status: String(conversacion.status ?? ''),
    weplash_has_dm: conversacion.hasDm === true,
    weplash_has_comment: conversacion.hasComment === true,
    weplash_source: String(mensaje.source ?? ''),

    // --- Marca de identidad ---
    identidad_manychat: false,

    // --- El aviso original, intacto, por si algun flujo lo necesita ---
    weplash_evento: aviso
  }
}];
